type AutoPromise<T> = Promise<Awaited<T>>;
import {
	assert, assertEquals, assertThrows, assertStrictEquals,
	} from '@std/assert'
import {doesNotThrow} from "node:assert"

import {
	undef, defined, notdefined, sleep,
	justThrow, croak, allStackFrames, TStackFrame, dumpFrame,
	TIterator, TAsyncIterator,
	} from 'base'
import {esc} from 'unicode'
import {LOG} from 'logger'
import {unify} from 'unify'
import {
	TVoidFunc, hash,
	isIterator, isAsyncIterator, isIterable,
	} from 'datatypes'
import {getOptions, truncStr, blockToArray} from 'llutils'
import {fromFSM, fromFSMdebug} from 'fsm'
import {TextTable} from 'text-table'
import {doParse} from 'hera-parse'
import {mkDir, clearDir, barf} from 'fsys'
import {compileFile} from 'automate'

let nextNum = 1

// ---------------------------------------------------------------------------

const getTestName = (): string => {

	const n = nextNum
	nextNum += 1
	const frame = getMyOutsideCaller()
	return `${n}. ` + (defined(frame) ? `line ${frame.line}` : "line ?")
}

// ---------------------------------------------------------------------------

export const equal = (
		value: unknown,
		expected: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assertEquals(value, expected))
	return
}

// ---------------------------------------------------------------------------

export const truthy = (
		value: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assert(value))
	return
}

// ---------------------------------------------------------------------------

export const falsy = (
		value: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assert((!value)))
	return
}

// ---------------------------------------------------------------------------

export const succeeds = (
	func: TVoidFunc,
	name?: string
	): void => {

	Deno.test(name || getTestName(), async (): AutoPromise<void> => {
		await func()
	})
	return
}

// ---------------------------------------------------------------------------

export const fails = (
	func: TVoidFunc,
	name?: string
	): void => {

	Deno.test(name || getTestName(), (): void => {
		justThrow(true)
		try {
			func()
			croak("in fails() but function succeeded")
		}
		catch (err) {}
		finally {
			justThrow(false)
		}
	})
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const generates = <TOut,>(
		value: TIterator<TOut>,
		expected: unknown,
		name?: string
		): void => {

	const lItems = [...value]
	Deno.test(name || getTestName(), () => assertEquals(lItems, expected))
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const generatesAsync = async <TOut,>(
		value: TAsyncIterator<TOut>,
		expected: unknown,
		name?: string
		): AutoPromise<void> => {

	const lItems = await Array.fromAsync(value)
	Deno.test(name || getTestName(), () => assertEquals(lItems, expected))
	return
}

// ---------------------------------------------------------------------------

export const same = (
		value: unknown,
		expected: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assertStrictEquals(value, expected))
	return
}

// ---------------------------------------------------------------------------

export const unifies = (
		value: unknown,
		expected: unknown,
		name?: string
		): void => {

	// --- if either value or expected is an iterator
	//     get an array from it
	if (isIterable(value)) {
		value = Array.from(value)
	}
	if (isIterable(expected)) {
		expected = Array.from(expected)
	}
	Deno.test(name || getTestName(), (): void => {
		unify(value, expected)
	})
	return
}

// ---------------------------------------------------------------------------

export const getMyOutsideCaller = (
	trace: boolean = false
	): (TStackFrame | undefined) => {

	const lFrames = Array.from(allStackFrames())
	if (trace) {
		LOG('-'.repeat(70))
		for (const frame of lFrames) {
			dumpFrame(frame)
		}
	}

	let mySrc: (string | undefined) = undef
	let outsideFrame: (TStackFrame | undefined) = undef

	return fromFSM(lFrames, [
		{
			stateFunc: (frame: TStackFrame): number => {
				if (
						   (frame.name === 'getMyOutsideCaller')
						&& frame.source.match(/\bunit-test\.lib\.(?:ts|civet)$/)
						) {
					if (trace) {
						LOG("getMyOutsideCaller found, set state to 1")
					}
					return 1
				}
				else {
					return 0
				}
			}
			},
		{
			stateFunc: (frame: TStackFrame): number => {
				const {source} = frame
				assert(defined(source), "source after getMyOutsideCaller is undef")
				mySrc = source
				return 2
			}
			},
		{
			stateFunc: (frame: TStackFrame): number => {
				const {source} = frame
				if (source === mySrc) {
					return 2
				}
				else {
					throw frame
				}
			}     // found !
			}
		])
}

// ---------------------------------------------------------------------------

export type TFileOp = {
		op: 'mkDir' | 'clearDir' | 'compile'
		path: string
		}
	| {
		op: 'barf'
		path: string
		contents: string
		}

// ---------------------------------------------------------------------------
// ASYNC

export const setDirTree = async (desc: string): AutoPromise<TFileOp[]> => {

	const lFileOps = await getFileOps(desc)
	await execFileOps(lFileOps)
	return lFileOps
}

// ---------------------------------------------------------------------------
// ASYNC

export const getFileOps = async (desc: string): AutoPromise<TFileOp[]> => {

	return await doParse<TFileOp[]>('dir-tree', desc)
}

// ---------------------------------------------------------------------------
// ASYNC

export const execFileOps = async (
		lFileOps: TFileOp[]
		): AutoPromise<void> => {

	for (const h of lFileOps) {
		switch(h.op) {
			case 'mkDir': {
				mkDir(h.path);break;
			}
			case 'clearDir': {
				clearDir(h.path);break;
			}
			case 'compile': {
				await compileFile(h.path);break;
			}
			case 'barf': {
				barf(h.path, h.contents);break;
			}
		}
	}
	return
}

// ---------------------------------------------------------------------------

export const fileOpsTable = (
		lFileOps: TFileOp[],
		hOptions: hash = {}
		): string => {

	type opt = {
		oneLine: boolean
		trunc: number
		}
	const {oneLine, trunc} = getOptions<opt>(hOptions, {
		oneLine: true,
		trunc: 32
		})

	const tt = new TextTable("l l l")
	tt.fullsep()
	tt.title('FILE OPS')
	tt.fullsep()
	tt.labels(['op', 'path', 'contents'])
	tt.sep()
	for (const h of lFileOps) {
		switch(h.op) {
			case 'barf': {
				const {path, contents} = h
				const str = contents || ''
				if (str.length === 0) {
					tt.data(['barf', path, '<empty>'])
				}
				else if (oneLine) {
					const output = truncStr(esc(str), trunc)
					tt.data(['barf', path, output])
				}
				else {
					const lLines = blockToArray(str)
					let i1 = 0;for (const line of lLines) {const i = i1++;
						const contents = truncStr(esc(lLines[i]), trunc)
						if (i === 0) {
							tt.data(['barf', path, contents])
						}
						else {
							tt.data(['', '', contents])
						}
					}
				};break;
			}
			default: {
				tt.data([h.op, h.path, ''])
			}
		}
	}
	tt.fullsep()
	return tt.asString()
}

